package com.dottags;

public enum DotPosition
{
	TOP_LEFT,
	TOP_RIGHT,
	BOTTOM_LEFT,
	BOTTOM_RIGHT
}

package com.dottags;

public enum DotStyle
{
	/** Soft gradient, glossy highlight, faint shadow and hairline ring. */
	GLOSSY,
	/** Plain single-color circle. */
	FLAT
}

package com.dottags;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(DotTagsConfig.GROUP)
public interface DotTagsConfig extends Config
{
	String GROUP = "dottags";

	@ConfigSection(name = "Dot style", description = "How the dot looks", position = 0)
	String styleSection = "style";

	@ConfigSection(name = "Group colors", description = "Color of each tag group", position = 1)
	String colorSection = "colors";

	@ConfigItem(keyName = "position", name = "Corner", description = "Which corner of the item the dot sits in",
		position = 0, section = styleSection)
	default DotPosition position()
	{
		return DotPosition.TOP_LEFT;
	}

	@Range(min = 3, max = 16)
	@ConfigItem(keyName = "dotSize", name = "Dot size", description = "Diameter of the dot in pixels",
		position = 1, section = styleSection)
	default int dotSize()
	{
		return 5;
	}

	@ConfigItem(keyName = "dotStyle", name = "Dot style", description = "Glossy = soft gradient with a highlight, Flat = plain circle",
		position = 1, section = styleSection)
	default DotStyle dotStyle()
	{
		return DotStyle.GLOSSY;
	}

	@Range(min = 10, max = 100)
	@ConfigItem(keyName = "opacity", name = "Opacity %", description = "How see-through the dot is (100 = solid)",
		position = 2, section = styleSection)
	default int opacity()
	{
		return 70;
	}

	@ConfigItem(keyName = "dotBorder", name = "Dark border", description = "Draw a thin dark ring so the dot stays visible on any item",
		position = 3, section = styleSection)
	default boolean dotBorder()
	{
		return false;
	}

	@ConfigItem(keyName = "showInBank", name = "Show in bank", description = "Also draw dots on items in the bank",
		position = 4, section = styleSection)
	default boolean showInBank()
	{
		return false;
	}

	@ConfigItem(keyName = "color1", name = "Group 1", description = "Color of group 1", position = 10, section = colorSection)
	default Color group1() { return new Color(0xFF1A1A); }

	@ConfigItem(keyName = "color2", name = "Group 2", description = "Color of group 2", position = 11, section = colorSection)
	default Color group2() { return new Color(0x1ED93C); }

	@ConfigItem(keyName = "color3", name = "Group 3", description = "Color of group 3", position = 12, section = colorSection)
	default Color group3() { return new Color(0x0A84FF); }

	@ConfigItem(keyName = "color4", name = "Group 4", description = "Color of group 4", position = 13, section = colorSection)
	default Color group4() { return new Color(0xFFCC00); }

	@ConfigItem(keyName = "color5", name = "Group 5", description = "Color of group 5", position = 14, section = colorSection)
	default Color group5() { return new Color(0xBF5AF2); }

	@ConfigItem(keyName = "color6", name = "Group 6", description = "Color of group 6", position = 15, section = colorSection)
	default Color group6() { return new Color(0xFFFFFF); }
}

package com.dottags;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Paint;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

class DotTagsOverlay extends WidgetItemOverlay
{
	private static final int PADDING = 2;
	private static final Color BORDER = new Color(0, 0, 0, 200);

	private final DotTagsPlugin plugin;
	private final DotTagsConfig config;

	@Inject
	DotTagsOverlay(DotTagsPlugin plugin, DotTagsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		showOnInventory();
		showOnBank();
	}

	@Override
	public void renderItemOverlay(Graphics2D g, int itemId, WidgetItem widgetItem)
	{
		if (!config.showInBank() && WidgetUtil.componentToInterface(widgetItem.getWidget().getId()) == InterfaceID.BANKMAIN)
		{
			return;
		}

		Color color = plugin.getTagColor(itemId);
		if (color == null)
		{
			return;
		}

		Rectangle b = widgetItem.getCanvasBounds();
		int size = config.dotSize();
		int x;
		int y;
		switch (config.position())
		{
			case TOP_RIGHT:
				x = b.x + b.width - size - PADDING;
				y = b.y + PADDING;
				break;
			case BOTTOM_LEFT:
				x = b.x + PADDING;
				y = b.y + b.height - size - PADDING;
				break;
			case BOTTOM_RIGHT:
				x = b.x + b.width - size - PADDING;
				y = b.y + b.height - size - PADDING;
				break;
			case TOP_LEFT:
			default:
				x = b.x + PADDING;
				y = b.y + PADDING;
				break;
		}

		float a = config.opacity() / 100f;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);

		if (config.dotBorder())
		{
			g.setColor(withAlpha(Color.BLACK, Math.min(a, BORDER.getAlpha() / 255f)));
			g.fill(new Ellipse2D.Float(x - 1, y - 1, size + 2, size + 2));
		}

		if (config.dotStyle() == DotStyle.FLAT)
		{
			g.setColor(withAlpha(color, a));
			g.fill(new Ellipse2D.Float(x, y, size, size));
			return;
		}

		drawGlossyDot(g, x, y, size, color, a);
	}

	private static void drawGlossyDot(Graphics2D g, float x, float y, float s, Color base, float a)
	{
		Paint oldPaint = g.getPaint();
		Stroke oldStroke = g.getStroke();

		// soft drop shadow: two faint, slightly offset layers
		g.setColor(withAlpha(Color.BLACK, 0.10f * a));
		g.fill(new Ellipse2D.Float(x - 0.6f, y + 0.2f, s + 1.2f, s + 1.4f));
		g.setColor(withAlpha(Color.BLACK, 0.18f * a));
		g.fill(new Ellipse2D.Float(x - 0.1f, y + 0.6f, s + 0.2f, s + 0.4f));

		// body: lighter at the top, slightly deeper at the bottom
		Ellipse2D.Float body = new Ellipse2D.Float(x, y, s, s);
		g.setPaint(new GradientPaint(x, y, withAlpha(mix(base, Color.WHITE, 0.10f), a),
			x, y + s, withAlpha(mix(base, Color.BLACK, 0.12f), a)));
		g.fill(body);

		// glossy highlight on the upper half
		float hw = s * 0.62f;
		float hh = s * 0.42f;
		float hx = x + (s - hw) / 2f;
		float hy = y + s * 0.08f;
		g.setPaint(new GradientPaint(hx, hy, withAlpha(Color.WHITE, 0.30f * a),
			hx, hy + hh, withAlpha(Color.WHITE, 0f)));
		g.fill(new Ellipse2D.Float(hx, hy, hw, hh));

		// hairline ring so it reads crisply against busy item art
		g.setPaint(withAlpha(Color.WHITE, 0.15f * a));
		g.setStroke(new BasicStroke(0.6f));
		g.draw(new Ellipse2D.Float(x + 0.3f, y + 0.3f, s - 0.6f, s - 0.6f));

		g.setPaint(oldPaint);
		g.setStroke(oldStroke);
	}

	private static Color withAlpha(Color c, float a)
	{
		int alpha = Math.max(0, Math.min(255, Math.round(a * 255f)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	private static Color mix(Color c, Color with, float t)
	{
		return new Color(
			Math.round(c.getRed() + (with.getRed() - c.getRed()) * t),
			Math.round(c.getGreen() + (with.getGreen() - c.getGreen()) * t),
			Math.round(c.getBlue() + (with.getBlue() - c.getBlue()) * t));
	}
}

package com.dottags;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ColorUtil;

@PluginDescriptor(
	name = "Dot Tags",
	description = "Shift + right-click an item to mark it with a small colored dot",
	tags = {"inventory", "tag", "dot", "highlight", "marker"}
)
public class DotTagsPlugin extends Plugin
{
	private static final String TAG_KEY_PREFIX = "tag_";
	private static final int GROUP_COUNT = 6;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DotTagsOverlay overlay;

	@Inject
	private DotTagsConfig config;

	@Provides
	DotTagsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DotTagsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	/** Returns the dot color for an item, or null if it isn't tagged. */
	Color getTagColor(int itemId)
	{
		Integer group = getTagGroup(itemId);
		return group == null ? null : groupColor(group);
	}

	private Integer getTagGroup(int itemId)
	{
		String v = configManager.getConfiguration(DotTagsConfig.GROUP, TAG_KEY_PREFIX + itemManager.canonicalize(itemId));
		if (v == null)
		{
			return null;
		}
		try
		{
			int g = Integer.parseInt(v);
			return g >= 1 && g <= GROUP_COUNT ? g : null;
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private void setTagGroup(int itemId, Integer group)
	{
		String key = TAG_KEY_PREFIX + itemManager.canonicalize(itemId);
		if (group == null)
		{
			configManager.unsetConfiguration(DotTagsConfig.GROUP, key);
		}
		else
		{
			configManager.setConfiguration(DotTagsConfig.GROUP, key, group);
		}
	}

	private Color groupColor(int group)
	{
		switch (group)
		{
			case 1: return config.group1();
			case 2: return config.group2();
			case 3: return config.group3();
			case 4: return config.group4();
			case 5: return config.group5();
			case 6: return config.group6();
			default: return null;
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return;
		}

		MenuEntry[] entries = event.getMenuEntries();
		for (int idx = entries.length - 1; idx >= 0; --idx)
		{
			MenuEntry entry = entries[idx];
			Widget w = entry.getWidget();
			if (w == null || !"Examine".equals(entry.getOption()))
			{
				continue;
			}

			int iface = WidgetUtil.componentToInterface(w.getId());
			if (iface != InterfaceID.INVENTORY && iface != InterfaceID.BANKSIDE && iface != InterfaceID.BANKMAIN)
			{
				continue;
			}

			int itemId = w.getItemId();
			if (itemId <= 0)
			{
				continue;
			}

			Integer current = getTagGroup(itemId);

			MenuEntry parent = client.getMenu().createMenuEntry(idx)
				.setOption("Dot tag")
				.setTarget(entry.getTarget())
				.setType(MenuAction.RUNELITE);
			Menu sub = parent.createSubMenu();

			for (int g = GROUP_COUNT; g >= 1; g--)
			{
				final int group = g;
				Color c = groupColor(g);
				sub.createMenuEntry(0)
					.setOption(ColorUtil.prependColorTag((current != null && current == g ? "● " : "○ ") + "Group " + g, c))
					.setType(MenuAction.RUNELITE)
					.onClick(e -> setTagGroup(itemId, group));
			}

			if (current != null)
			{
				sub.createMenuEntry(0)
					.setOption("Remove dot")
					.setType(MenuAction.RUNELITE)
					.onClick(e -> setTagGroup(itemId, null));
			}
			break;
		}
	}
}

package com.dottags;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DotTagsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DotTagsPlugin.class);
		RuneLite.main(args);
	}
}
